starter.css:
h1 {
  color: #8B2E2E;
  text-align: center;
  margin-bottom: 24px;
}
.animation-group {
  display: flex;
  gap: 16px;
  flex-wrap: wrap;
  justify-content: center;
}
.anim-card {
  background: #FFFAF2;
  border: 1px solid #D4C5A9;
  border-radius: 12px;
  padding: 24px;
  text-align: center;
  width: 180px;
  cursor: pointer;
}
.card-icon {
  font-size: 32px;
  display: block;
  margin-bottom: 8px;
}
.anim-card strong {
  display: block;
  color: #3D2B1F;
  margin-bottom: 4px;
}
.anim-card p {
  color: #6B5A4E;
  font-size: 12px;
  margin: 0;
}
/* 渐强过渡 */
.fade-card {
  transition: all 0.3s ease;
}
.fade-card:hover {
  background: #8B2E2E;
  color: #fff;
  transform: scale(1.05);
  box-shadow: 0 8px 24px rgba(61, 43, 31, 0.16);
}
.fade-card:hover strong,
.fade-card:hover p {
  color: #fff;
}
/* 跳动 */
.bounce-card:hover {
  animation: bounce 0.6s ease;
}
@keyframes bounce {
  0%, 100% { transform: translateY(0); }
  25% { transform: translateY(-12px); }
  75% { transform: translateY(-4px); }
}
/* 自动脉动 */
.auto-pulse {
  animation: pulse 2s ease-in-out infinite;
  border-color: #C9A96E;
}
@keyframes pulse {
  0%, 100% { opacity: 1; transform: scale(1); }
  50% { opacity: 0.7; transform: scale(1.03); }
}
